<?php require __DIR__.'/app/bootstrap.php';$u=require_user();$servers=[];$error='';$serviceMap=[];try{$q=db()->prepare("SELECT id,ptero_identifier,ptero_server_id FROM services WHERE user_id=? AND status<>'terminated'");$q->execute([$u['id']]);foreach($q->fetchAll() as $svc){if(!empty($svc['ptero_identifier']))$serviceMap[(string)$svc['ptero_identifier']]=(int)$svc['id'];}}catch(Throwable $e){}if($u['ptero_client_key']){try{$r=ptero('/');$servers=$r['data']??[];}catch(Throwable $e){$error=$e->getMessage();}}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FoxNetwork | My Dashboard</title><link rel="stylesheet" href="/css/fontawesome-all.min.css"><link rel="stylesheet" href="/assets/portal.css?v=4.2"></head><body><div class="app"><aside class="side"><div class="brand"><img src="/images/logo.png"><span>FOX<b>NETWORK</b></span></div><nav class="nav"><a class="active" href="/"><span class="nav-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M3 10.5 12 3l9 7.5v9a1.5 1.5 0 0 1-1.5 1.5H15v-6H9v6H4.5A1.5 1.5 0 0 1 3 19.5z"/></svg></span><span>Overview</span></a><a href="/"><span class="nav-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M7.5 7h9a5 5 0 0 1 4.8 6.4l-1.2 4A2.2 2.2 0 0 1 16.3 18l-1.1-1.5H8.8L7.7 18a2.2 2.2 0 0 1-3.8-.6l-1.2-4A5 5 0 0 1 7.5 7Z"/><path d="M7 10v4M5 12h4M16.5 10.8h.01M18.5 13.2h.01"/></svg></span><span>My Servers</span></a><a href="/store.php"><span class="nav-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M3 4h2l2.2 10.2a2 2 0 0 0 2 1.6h7.9a2 2 0 0 0 1.9-1.4L21 8H6"/><circle cx="10" cy="19" r="1.3"/><circle cx="18" cy="19" r="1.3"/></svg></span><span>Store</span></a><a href="/orders.php"><span class="nav-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M6 3h12v18l-3-2-3 2-3-2-3 2z"/><path d="M9 8h6M9 12h6M9 16h4"/></svg></span><span>Orders</span></a><a href="/billing.php"><span class="nav-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><rect x="3" y="5" width="18" height="14" rx="2"/><path d="M3 10h18M7 15h4"/></svg></span><span>Billing</span></a><a href="/support.php"><span class="nav-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="3"/><path d="m5.6 5.6 4.3 4.3m4.2 4.2 4.3 4.3m0-12.8-4.3 4.3m-4.2 4.2-4.3 4.3"/></svg></span><span>Support</span></a></nav><nav class="nav bottom"><a href="/settings.php"><span class="nav-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .3 1.9l.1.1-2.8 2.8-.1-.1a1.7 1.7 0 0 0-1.9-.3 1.7 1.7 0 0 0-1 1.6v.2h-4V21a1.7 1.7 0 0 0-1-1.6 1.7 1.7 0 0 0-1.9.3l-.1.1L4.2 17l.1-.1a1.7 1.7 0 0 0 .3-1.9A1.7 1.7 0 0 0 3 14H2.8v-4H3a1.7 1.7 0 0 0 1.6-1 1.7 1.7 0 0 0-.3-1.9L4.2 7 7 4.2l.1.1A1.7 1.7 0 0 0 9 4.6a1.7 1.7 0 0 0 1-1.6v-.2h4V3a1.7 1.7 0 0 0 1 1.6 1.7 1.7 0 0 0 1.9-.3l.1-.1L19.8 7l-.1.1a1.7 1.7 0 0 0-.3 1.9 1.7 1.7 0 0 0 1.6 1h.2v4H21a1.7 1.7 0 0 0-1.6 1Z"/></svg></span><span>Account Settings</span></a><a href="/logout.php"><span class="nav-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M10 5H5v14h5M14 8l4 4-4 4M18 12H9"/></svg></span><span>Sign out</span></a></nav></aside><main class="main"><header><div class="profile"><div><b><?=e($u['name'])?></b><div class="muted" style="font-size:12px"><?=e(ucfirst($u['role']))?></div></div><div class="avatar"><?=e(strtoupper(substr($u['name'],0,1)))?></div></div></header><div class="content"><div class="eyebrow">FoxNetwork Control Center</div><h1><?=greeting()?>, <?=e(explode(' ',$u['name'])[0])?>.</h1><div class="muted">Your real Pterodactyl servers, without the complexity.</div><?php if(!$u['ptero_client_key']):?><div class="notice">Connect your Pterodactyl account in <a class="link" href="/settings.php">Account Settings</a> to load your servers.</div><?php endif?><?php if($error):?><div class="error"><?=e($error)?></div><?php endif?><section class="stats"><div class="stat"><span class="muted">Servers</span><strong><?=count($servers)?></strong></div><div class="stat"><span class="muted">Online</span><strong id="online-count">—</strong></div><div class="stat"><span class="muted">Platform</span><strong style="font-size:18px">Pterodactyl</strong></div></section><section class="card"><div class="cardhead"><b>MY SERVERS</b><span class="muted"><?=count($servers)?> server<?=count($servers)==1?'':'s'?></span></div><div class="servers"><?php if(!$servers):?><div class="empty muted">No servers found.</div><?php endif?><?php foreach($servers as $row):$a=$row['attributes'];$id=$a['identifier'];$serviceId=(int)($serviceMap[(string)$id]??0);?><article class="server" data-server="<?=e($id)?>"><div class="server-top"><div><div class="server-name"><?=e($a['name'])?></div><div class="muted"><?=e($a['description']?:'FoxNetwork game server')?></div></div><div class="status offline" data-status>LOADING…</div></div><div class="metrics"><div class="metric"><span class="muted">CPU</span><b data-cpu>—</b></div><div class="metric"><span class="muted">Memory</span><b data-memory>—</b></div><div class="metric"><span class="muted">Disk</span><b data-disk>—</b></div></div><div class="buttons"><button class="btn primary" data-power="start">▶ Start</button><button class="btn" data-power="restart">↻ Restart</button><button class="btn" data-power="stop">■ Stop</button><a class="btn primary" href="/server.php?id=<?=e($id)?>">Manage Server</a><?php if($serviceId>0):?><a class="btn" href="/upgrades.php?service=<?=e($serviceId)?>">Upgrade</a><?php if($serviceId):?><a class="btn" href="/lifecycle.php?service=<?=e($serviceId)?>">Renew / Billing</a><?php endif?><?php else:?><span class="btn" style="opacity:.5;cursor:not-allowed" title="Link this Pterodactyl server to a FoxNetwork service first.">Upgrade unavailable</span><?php endif?><a class="btn" href="<?=e(rtrim(cfg('pterodactyl.url'),'/').'/server/'.$id)?>" target="_blank">Advanced Panel ↗</a></div></article><?php endforeach?></div></section></div></main></div><script>const CSRF=<?=json_encode(csrf())?>;function mb(n){return (n/1024/1024).toFixed(1)+' MB'}async function refresh(card){const id=card.dataset.server;try{const r=await fetch('/api/resources.php?id='+encodeURIComponent(id));const j=await r.json();if(!j.ok)throw Error(j.error);const a=j.data.attributes,s=a.current_state;const st=card.querySelector('[data-status]');st.textContent=s.toUpperCase();st.className='status '+(s==='running'?'online':(s==='starting'?'starting':'offline'));card.querySelector('[data-cpu]').textContent=(a.resources.cpu_absolute||0).toFixed(1)+'%';card.querySelector('[data-memory]').textContent=mb(a.resources.memory_bytes||0);card.querySelector('[data-disk]').textContent=mb(a.resources.disk_bytes||0);}catch(e){card.querySelector('[data-status]').textContent='UNAVAILABLE';}}async function power(card,signal){const buttons=card.querySelectorAll('button');buttons.forEach(b=>b.disabled=true);try{const r=await fetch('/api/power.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':CSRF},body:JSON.stringify({id:card.dataset.server,signal})});const text=await r.text();let j;try{j=JSON.parse(text)}catch(_){throw Error('Portal returned an invalid response (HTTP '+r.status+'). Refresh and try again.')}if(!j.ok)throw Error(j.error||'Power action failed');setTimeout(()=>refresh(card),700);setTimeout(()=>refresh(card),2000);setTimeout(()=>refresh(card),5000);}catch(e){alert(e.message)}finally{setTimeout(()=>buttons.forEach(b=>b.disabled=false),1000)}}document.querySelectorAll('.server').forEach(card=>{refresh(card);card.querySelectorAll('[data-power]').forEach(b=>b.onclick=()=>power(card,b.dataset.power));});setInterval(()=>document.querySelectorAll('.server').forEach(refresh),10000);</script></body></html>